-- Make the bucket private so storage.objects SELECT is no longer broadly readable.
-- Files can still be served via signed URLs / public URLs generated by the edge function.
UPDATE storage.buckets
SET public = false
WHERE id = 'tts-cache';

-- Drop any broad public SELECT policies on this bucket.
DROP POLICY IF EXISTS "Public can read tts cache" ON storage.objects;
DROP POLICY IF EXISTS "Anyone can read tts cache" ON storage.objects;
DROP POLICY IF EXISTS "tts-cache select" ON storage.objects;
DROP POLICY IF EXISTS "Public read tts-cache" ON storage.objects;
DROP POLICY IF EXISTS "Public can select tts-cache" ON storage.objects;